    .modal-close:hover { background: var(--gray-100); color: var(--gray-800); }
    .modal-body { padding: 20px 28px 28px; }
    .modal-subtitle {
      color: var(--gray-600);
      font-size: 0.92rem;
      margin-bottom: 20px;
    }
    .modal-amounts {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 10px;
      margin-bottom: 16px;
    }
    .modal-amount-btn {
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 14px 8px;
      text-align: center;
      cursor: pointer;
      background: var(--white);
      transition: border-color var(--transition), background var(--transition);
    }
    .modal-amount-btn:hover { border-color: var(--red); background: #fff5f6; }
    .modal-amount-btn.selected { border-color: var(--red); background: #fff5f6; }
    .modal-amount-btn .amount-value { color: var(--navy); font-size: 1.2rem; }
    .modal-amount-btn .amount-impact { color: var(--gray-600); }
    .modal-custom {
      display: flex;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      overflow: hidden;
      margin-bottom: 20px;
      transition: border-color var(--transition);
