      height: 38px;
      background: var(--red);
    }
    .footer-logo .logo-name {
      font-size: 0.95rem;
      font-weight: 800;
      color: var(--white);
      line-height: 1.1;
    }
    .footer-brand p {
      font-size: 0.875rem;
      line-height: 1.65;
      margin-bottom: 20px;
    }
    .social-links { display: flex; gap: 10px; }
    .social-link {
      width: 36px;
      height: 36px;
      border-radius: 8px;
      background: rgba(255,255,255,0.08);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 0.9rem;
      color: rgba(255,255,255,0.7);
      transition: background var(--transition), color var(--transition);
    }
    .social-link:hover { background: var(--red); color: var(--white); }
    .footer-col h4 {
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      color: var(--white);
      margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
    .footer-col ul li a {
      font-size: 0.875rem;
      color: rgba(255,255,255,0.6);
      transition: color var(--transition);
    }
    .footer-col ul li a:hover { color: var(--white); }
    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 20px 0;
      font-size: 0.8rem;
      color: rgba(255,255,255,0.4);
      flex-wrap: wrap;
    }
    .footer-bottom a { color: rgba(255,255,255,0.4); transition: color var(--transition); }
    .footer-bottom a:hover { color: rgba(255,255,255,0.75); }

    /* ─── Counter animation ─── */
    .counter { display: inline-block; }

    /* ─── Responsive ─── */
    @media (max-width: 1024px) {
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
    }
    @media (max-width: 768px) {
      .main-nav { display: none; }
      .hamburger { display: flex; }
      .hero-content { padding: 60px 0; }
      .hero-stats { gap: 20px; }
      .mission-grid { grid-template-columns: 1fr; gap: 40px; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .involve-grid { grid-template-columns: 1fr; }
      .news-card { flex: 0 0 calc(80% - 16px); }
      .donate-cta-inner { grid-template-columns: 1fr; gap: 40px; }
